import {setVrsText} from './branding.mjs';
const $=selector=>document.querySelector(selector),status=$('[data-status]'),login=$('[data-login]'),panel=$('[data-panel]');
let key=new URLSearchParams(location.hash.slice(1)).get('activar');if(location.hash)history.replaceState(null,'',location.pathname);
async function api(path,body){const response=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});const result=await response.json();if(!response.ok){if(response.status===401){panel.hidden=true;login.hidden=false;}throw new Error(result.error||'No se ha podido completar la operación.');}return result;}
function node(tag,text){const el=document.createElement(tag);if(text)setVrsText(el,text);return el;}
async function refresh(){const list=$('[data-list]');status.textContent='Cargando anuncios…';try{const items=await api('admin/listings?status='+$('[data-filter]').value);list.replaceChildren();for(const item of items){const card=node('article');card.className='admin-card';card.append(node('h2',item.title),node('p',`${item.price.toLocaleString('es-ES')} € · ${item.category}`),node('p',item.description),node('p',`Estado: ${item.condition}\nCompatibilidad: ${item.compatibility}\nLocalidad: ${item.location}\nVendedor: ${item.seller}`));for(const src of item.images){const a=node('a'),image=node('img');a.href=src;a.target='_blank';a.rel='noopener noreferrer';image.src=src;image.alt='Foto de '+item.title;a.append(image);card.append(a);}const contact=node('a','Contacto del vendedor');contact.href=item.contactUrl;contact.rel='noopener noreferrer';card.append(contact);const note=node('textarea');note.placeholder='Nota privada de revisión (opcional)';note.maxLength=500;note.setAttribute('aria-label','Nota privada de revisión');note.value=item.reviewNote||'';card.append(note);for(const [action,label] of (item.status==='pending'?[['approve','Aprobar y publicar'],['reject','Rechazar']]:item.status==='approved'?[['sold','Marcar vendido'],['withdraw','Retirar anuncio']]:[])){const button=node('button',label);button.addEventListener('click',async()=>{button.disabled=true;try{await api('admin/listings/'+item.id,{action,note:note.value});await refresh();status.textContent=action==='approve'?'Anuncio publicado en el mercadillo.':'Anuncio actualizado.';}catch(error){status.textContent=error.message;button.disabled=false;}});card.append(button);}list.append(card);}status.textContent=items.length?`${items.length} anuncios.`:'No hay anuncios en esta lista.';}catch(error){status.textContent=error.message;}}
async function enter(user){key=null;login.hidden=true;panel.hidden=false;$('[data-user]').textContent=user.email;await refresh();}
if(key){$('[data-login-title]').textContent='Activar acceso privado';$('[data-setup-copy]').hidden=false;login.elements.password.autocomplete='new-password';}
login.addEventListener('submit',async event=>{event.preventDefault();const button=login.querySelector('button');button.disabled=true;status.textContent='Comprobando acceso…';try{const data=Object.fromEntries(new FormData(login));if(key)data.key=key;await enter(await api(key?'admin/setup':'admin/login',data));login.reset();}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
$('[data-filter]').addEventListener('change',refresh);$('[data-refresh]').addEventListener('click',refresh);$('[data-logout]').addEventListener('click',async()=>{try{await api('admin/logout',{});panel.hidden=true;login.hidden=false;status.textContent='Sesión cerrada.';}catch(error){status.textContent=error.message;}});
$('[data-add-user]').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');button.disabled=true;try{await api('admin/users',Object.fromEntries(new FormData(form)));form.reset();status.textContent='Acceso creado. El otro administrador ya puede iniciar sesión con su correo y contraseña.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
try{await enter(await api('admin/session'));}catch(error){if(!key)status.textContent='Acceso privado para Alberto y Raúl.';}
